def compare_lists(list1, list2):
    set1 = set(map(tuple, list1))
    set2 = set(map(tuple, list2))

    if set1 == set2:
        print("Both lists are the same.")
    else:
        print("Differences found:")
        print("Only in list1:", set1 - set2)
        print("Only in list2:", set2 - set1)
        
        
